mapper.select:
SELECT * FROM oa_consumable_ledger WHERE tenant_id = #{tenantId}
    AND source_biz_type = 'CONSUMABLE_REQUEST' AND source_biz_id = #{requestId}
ORDER BY ledger_id

SELECT * FROM oa_consumable_ledger WHERE tenant_id = #{tenantId}
AND consumable_id = #{query.consumableId}
AND transaction_type = #{query.transactionType}
AND source_biz_type = #{query.sourceBizType}
AND source_biz_id = #{query.sourceBizId}
AND operate_time >= #{query.from}
AND operate_time < #{query.to}
ORDER BY ledger_id DESC

SELECT CAST(consumable_id AS CHAR) AS consumable_id, MAX(consumable_name) AS name, unit, CAST(dept_id AS CHAR) AS dept_id, MAX(dept_name) AS dept_name, CAST(beneficiary_id AS CHAR) AS beneficiary_id, MAX(beneficiary_name) AS beneficiary_name, -SUM(CASE WHEN transaction_type = 'OUTBOUND' THEN quantity ELSE 0 END) AS issued_quantity, SUM(CASE WHEN transaction_type = 'RETURN' THEN quantity ELSE 0 END) AS returned_quantity, -SUM(quantity) AS net_quantity, -SUM(CASE WHEN transaction_type = 'OUTBOUND' THEN amount ELSE 0.00 END) AS issued_amount, SUM(CASE WHEN transaction_type = 'RETURN' THEN amount ELSE 0.00 END) AS returned_amount, -SUM(amount) AS net_amount FROM oa_consumable_ledger WHERE tenant_id = #{tenantId} AND source_biz_type = 'CONSUMABLE_REQUEST' AND transaction_type IN ('OUTBOUND', 'RETURN') AND operate_time >= #{query.from} AND operate_time < #{query.to} AND consumable_id = #{query.consumableId} AND dept_id = #{query.deptId} AND beneficiary_id = #{query.applicantId}
AND (1 = 0 OR beneficiary_id = #{scopeUserId}
OR dept_id IN #{department}
)
GROUP BY consumable_id, unit , dept_id , beneficiary_id ORDER BY consumable_id, unit , dept_id , beneficiary_id
